-- Single UPDATE statement for all recipes
-- Using CASE to update 100 recipes in one query

UPDATE recipes_database
SET steps_en = CASE id
  WHEN 1 THEN '1. Cut tofu into cubes and marinate 20 minutes | 2. Cut vegetables into equal pieces | 3. Alternate on skewers | 4. Grill 10 minutes turning | 5. Cook quinoa | 6. Serve skewers on quinoa, sprinkle with sesame'
